bool MainDialog::runKuroshioExtract()
{
	ncdfLog("[kuro] runKuroshioExtract: start\n");
	if (m_isLoading) {
		m_textCtrlFeatReadout->SetValue(wxString::FromUTF8("正在加载数据，请稍候再提取"));
		return false;
	}

	// 提取必须有 U/V：置标志让 readTimeStepData 无论如何都读入流场
	// （否则“显示流速”未勾选时 ucurr 为空，提取会误报无数据）
	m_kuroshioNeedUV = true;

	// 需要当前时间步的 U/V；缺失时按特征刷新的 phase-3 模式补读
	if (!myMessage.hasCurrent()) {
		if (m_lastSelectedTimeIndex < 0) {
			m_textCtrlFeatReadout->SetValue(wxString::FromUTF8("请先在左侧目录树选择一个时间步"));
			return false;
		}
		ncdfOverlayFactory *pof = pPlugIn ? pPlugIn->GetncdfOverlayFactory() : NULL;
		if (pof) pof->m_bReadyToRender = false;
		bool rd = readTimeStepData(myMessage);
		if (pof && rd) {
			pof->setData(this, pPlugIn, myMessage, myMessage.numberOfPoints,
			             myMessage.firstGridPointLat, myMessage.firstGridPointLong,
			             myMessage.lastGridPointLat, myMessage.lastGridPointLong);
		}
		if (pof) pof->m_bReadyToRender = true;
		if (!rd || !myMessage.hasCurrent()) {
			m_textCtrlFeatReadout->SetValue(wxString::FromUTF8("当前文件/时间步没有可用的 U/V 流场"));
			return false;
		}
	}

	m_kuroshio.wantBoundaries = true;
	m_kuroshio.setLandMask((pPlugIn && pPlugIn->m_landMask.valid()) ? &pPlugIn->m_landMask : NULL);

	// 先算进局部结果，算完再整体替换：提取耗时数秒，
	// 若一开始就把 m_kuroshioResult 清空，期间的重绘会看到空结果。
	KuroshioAxisResult fresh;
	{
		wxBusyCursor busy;
		wxBusyInfo info(wxString::FromUTF8("正在提取黑潮主轴（流线约束最大流速法）…"));
		m_kuroshio.extract(myMessage, fresh);
	}
	m_kuroshioResult = fresh;

	m_textCtrlFeatReadout->SetValue(m_kuroshioResult.message);
	ncdfLog("[kuro] runKuroshioExtract: ok=%d %s\n", (int)m_kuroshioResult.ok,
	        (const char*)m_kuroshioResult.message.mb_str(wxConvUTF8));
	RequestRefresh(m_parent);
	return m_kuroshioResult.ok;
}

bool MainDialog::exportKuroshioCsv()
{
	if (!m_kuroshioResult.ok || m_kuroshioResult.axis.empty()) {
		wxMessageBox(wxString::FromUTF8("尚无提取结果，请先点击“提取主轴”。"),
		             wxString::FromUTF8("导出黑潮主轴"), wxOK | wxICON_INFORMATION, this);
		return false;
	}

	wxString defName = wxString::Format(_T("kuroshio_axis_%s.csv"),
		(myMessage.dataDateTime.IsValid()
			? myMessage.dataDateTime.Format(_T("%Y%m%d_%H%M"))
			: wxString::Format(_T("t%d"), myMessage.timeIndex)));
	wxFileDialog dlg(this, wxString::FromUTF8("导出黑潮主轴结果"),
	                 wxEmptyString, defName, _T("CSV files (*.csv)|*.csv|All files (*.*)|*.*"),
	                 wxFD_SAVE | wxFD_OVERWRITE_PROMPT);
	if (dlg.ShowModal() != wxID_OK) return false;

	wxFile fout(dlg.GetPath(), wxFile::write);
	if (!fout.IsOpened()) {
		wxMessageBox(wxString::FromUTF8("无法写入文件：") + dlg.GetPath(),
		             wxString::FromUTF8("导出黑潮主轴"), wxOK | wxICON_ERROR, this);
		return false;
	}

	size_t N = m_kuroshioResult.axis.size() / 2;
	wxString head;
	head += _T("# Kuroshio axis and boundaries -- streamline-constrained maximum velocity method\n");
	head += _T("# Wang et al. (2026, Scientific Data) algorithm, ncdf_pi extraction\n");
	head += _T("# source_file,") + myMessage.fileName + _T("\n");
	head += wxString::Format(_T("# time,%s\n"),
		(myMessage.dataDateTime.IsValid()
			? myMessage.dataDateTime.Format(_T("%Y-%m-%d %H:%M:%S"))
			: wxString::Format(_T("index %d"), myMessage.timeIndex)));
	head += wxString::Format(_T("# n_axis,%d  length_km,%.2f  mean_speed_ms,%.3f  max_speed_ms,%.3f\n"),
		m_kuroshioResult.nAxis, m_kuroshioResult.lengthKm,
		m_kuroshioResult.meanSpeed, m_kuroshioResult.maxSpeed);
	head += _T("# segments_ABCDE,");
	for (int s = 0; s < 5; s++)
		head += wxString::Format(_T("%s%d"), s ? _T(" ") : _T(""), m_kuroshioResult.segFound[s]);
	head += _T("\n");
	head += _T("idx,lon,lat,left_lon,left_lat,right_lon,right_lat\n");
	fout.Write(head);

	bool hasB = (m_kuroshioResult.left.size() >= N * 2 &&
	             m_kuroshioResult.right.size() >= N * 2);
	for (size_t i = 0; i < N; i++) {
		wxString line = wxString::Format(_T("%d,%.6f,%.6f"), (int)i,
			m_kuroshioResult.axis[2 * i], m_kuroshioResult.axis[2 * i + 1]);
		if (hasB) {
			// 用字符串拼接而非 Format("%s", wxString)：可变参 %s 传 wxString 未定义
			double llon = m_kuroshioResult.left[2 * i], llat = m_kuroshioResult.left[2 * i + 1];
			double rlon = m_kuroshioResult.right[2 * i], rlat = m_kuroshioResult.right[2 * i + 1];
			line += _T(",");
			line += std::isfinite(llon) ? wxString::Format(_T("%.6f"), llon) : wxString();
			line += _T(",");
			line += std::isfinite(llat) ? wxString::Format(_T("%.6f"), llat) : wxString();
			line += _T(",");
			line += std::isfinite(rlon) ? wxString::Format(_T("%.6f"), rlon) : wxString();
			line += _T(",");
			line += std::isfinite(rlat) ? wxString::Format(_T("%.6f"), rlat) : wxString();
		} else {
			line += _T(",,,,,");
		}
		line += _T("\n");
		fout.Write(line);
	}
	fout.Close();

	m_textCtrlFeatReadout->SetValue(
		wxString::FromUTF8("已导出 ") << (int)N << wxString::FromUTF8(" 点到\n") << dlg.GetPath());
	return true;
}

// ---------------------------------------------------------------------------
// Canvas mouse events (P2): region-pick drag + feature icon click panels.
bool MainDialog::onCanvasMouse(wxMouseEvent& ev)
{
	ncdfOverlayFactory *pof = pPlugIn ? pPlugIn->GetncdfOverlayFactory() : NULL;
	PlugIn_ViewPort *vpc = (pof && pof->m_bHasVpCopy) ? &pof->m_vpCopy : NULL;
	if (!pof || !vpc) return false;

	if (ev.LeftDown() && m_regionPickMode) {
		m_rpDragging = true;
		m_rpX0 = ev.GetX(); m_rpY0 = ev.GetY();
		selectionRectangle.topLat = selectionRectangle.bottomLat = ncdf_NOTDEF;
		return true;
	}
	if (ev.Dragging() && m_regionPickMode && m_rpDragging && ev.LeftIsDown()) {
		GetCanvasLLPix(vpc, wxPoint(m_rpX0, m_rpY0), &selectionRectangle.topLat, &selectionRectangle.topLon);
		GetCanvasLLPix(vpc, wxPoint(ev.GetX(), ev.GetY()), &selectionRectangle.bottomLat, &selectionRectangle.bottomLon);
		pof->setSelectionRectangle(&selectionRectangle);
		pof->renderSelectionRectangle = true;
		RequestRefresh(m_parent);
		return true;
	}
	if (ev.LeftUp()) {
		if (m_regionPickMode && m_rpDragging) {
			m_rpDragging = false;
			m_regionPickMode = false;
			pof->renderSelectionRectangle = false;
			if (selectionRectangle.bottomLat != ncdf_NOTDEF) {
				double la0 = wxMin(selectionRectangle.topLat, selectionRectangle.bottomLat);
				double la1 = wxMax(selectionRectangle.topLat, selectionRectangle.bottomLat);
				double lo0 = wxMin(selectionRectangle.topLon, selectionRectangle.bottomLon);
				double lo1 = wxMax(selectionRectangle.topLon, selectionRectangle.bottomLon);
				m_textFeatLatMin->SetValue(wxString::Format(_T("%.2f"), la0));
				m_textFeatLatMax->SetValue(wxString::Format(_T("%.2f"), la1));
				m_textFeatLonMin->SetValue(wxString::Format(_T("%.2f"), lo0));
				m_textFeatLonMax->SetValue(wxString::Format(_T("%.2f"), lo1));
				selectionRectangle.bottomLat = ncdf_NOTDEF;
				applyFeatureRegion();
			}
			RequestRefresh(m_parent);
			return true;
		}
		if (!m_regionPickMode) {
			// any canvas click first dismisses an open popup
			FeatureRender::clearPopup();
			wxString panel;
			bool hit = hitTestFeatureAt(ev.GetX(), ev.GetY(), panel);
			{
				ncdfOverlayFactory *pof2 = pPlugIn ? pPlugIn->GetncdfOverlayFactory() : NULL;
				size_t nE = 0, nJ = 0, nF = 0;
				double la2 = 0, lo2 = 0;
				int rtx = -1, rty = -1, nx = -9999, ny = -9999;
				double bestD2 = 1e18;
				if (pof2 && pof2->m_bHasVpCopy) {
					const FeatureSet &fs2 = pof2->m_featureEngine.features();
					PlugIn_ViewPort *vc2 = &pof2->m_vpCopy;
					nE = fs2.eddies.size(); nJ = fs2.jets.size(); nF = fs2.fronts.size();
					GetCanvasLLPix(vc2, wxPoint(ev.GetX(), ev.GetY()), &la2, &lo2);
					wxPoint rt;
					GetCanvasPixLL(vc2, &rt, la2, lo2);
					rtx = rt.x; rty = rt.y;
					for (size_t e2 = 0; e2 < fs2.eddies.size(); e2++) {
						wxPoint pt2;
						GetCanvasPixLL(vc2, &pt2, fs2.eddies[e2].clat, fs2.eddies[e2].clon);
						double ddx = (double)pt2.x - ev.GetX(), ddy = (double)pt2.y - ev.GetY();
						double d2 = ddx * ddx + ddy * ddy;
						if (d2 < bestD2) { bestD2 = d2; nx = pt2.x; ny = pt2.y; }
					}
				}
				ncdfLog("[mouse] click at (%d,%d) hit=%d panelLen=%d feat(e=%zu j=%zu f=%zu) ll=(%.3f,%.3f) rt=(%d,%d) nearIcon=(%d,%d) d=%.0f\n",
					ev.GetX(), ev.GetY(), (int)hit, (int)panel.length(),
					nE, nJ, nF, la2, lo2, rtx, rty, nx, ny, sqrt(bestD2));
			}
			if (hit) {
				m_textCtrlFeatReadout->SetValue(panel);   // keep readout in sync
				showFeaturePopup(ev.GetX(), ev.GetY(), panel);
				return true;   // consumed: click on a feature icon
			}
		}
	}
	return false;
}

// Popup panel anchored at the clicked icon (P3-prep UX fix): a small
// stay-on-top mini frame showing the feature metric panel.
void MainDialog::showFeaturePopup(int canvasX, int canvasY, const wxString &panel)
{
	// GL-drawn popup only (legend-style rendering path); the wx window
	// approach is fully removed -- it double-popped alongside the GL box.
	ncdfLog("[popup] show len=%d first=%.60s\n", (int)panel.length(), (const char*)panel.mb_str());
	FeatureRender::setPopup(panel, m_selFeatLon, m_selFeatLat);
	(void)canvasX; (void)canvasY;
}

// Reposition the popup to follow its feature anchor (called every render frame).
void MainDialog::updateFeaturePopupPos(PlugIn_ViewPort *vp)
{
	if (!m_featPopup || !vp) return;
	if (m_selFeatLon < -9000) return;
	wxPoint pt;
	GetCanvasPixLL(vp, &pt, m_selFeatLat, m_selFeatLon);
	wxWindow *canvas = GetOCPNCanvasWindow();
	if (!canvas) return;
	wxSize cs = canvas->GetClientSize();
	// hide when the anchor is far outside the canvas
	if (pt.x < -200 || pt.y < -200 || pt.x > cs.x + 200 || pt.y > cs.y + 200) {
		if (m_featPopup->IsShown()) m_featPopup->Hide();
		return;
	}
	wxPoint sp = canvas->ClientToScreen(wxPoint(pt.x + 14, pt.y + 14));
	if (!m_featPopup->IsShown()) m_featPopup->Show();
	m_featPopup->Move(sp);
}

bool MainDialog::hitTestFeatureAt(int sx, int sy, wxString &panel)
{
	ncdfOverlayFactory *pof = pPlugIn ? pPlugIn->GetncdfOverlayFactory() : NULL;
	PlugIn_ViewPort *vpc = (pof && pof->m_bHasVpCopy) ? &pof->m_vpCopy : NULL;
	if (!pof || !vpc) return false;
	const FeatureSet &fs = pof->m_featureEngine.features();
	m_selFeatLon = -9999; m_selFeatLat = -9999;

	// body hit: convert click -> lat/lon -> shared body test
	double lat = 0, lon = 0;
	GetCanvasLLPix(vpc, wxPoint(sx, sy), &lat, &lon);
	int idx = -1;
	int kind = pof->m_featureEngine.hitTestAt(lon, lat, idx);

	// icon fallback: 15 px around anchors (precise icon clicks)
	if (kind < 0) {
		double best = 15.0 * 15.0;
		wxPoint pt;
		for (size_t e = 0; e < fs.eddies.size(); e++) {
			GetCanvasPixLL(vpc, &pt, fs.eddies[e].clat, fs.eddies[e].clon);
			double d2 = (pt.x - sx) * (pt.x - sx) + (pt.y - sy) * (pt.y - sy);
			if (d2 < best) { best = d2; kind = 0; idx = (int)e; }
		}
		for (size_t t = 0; t < fs.jets.size(); t++) {
			const JetFeature &jf = fs.jets[t];
			if (jf.vCnt < 1) continue;
			int k = jf.vCnt / 2;
			GetCanvasPixLL(vpc, &pt, fs.arena[(size_t)(jf.vOff + 2 * k + 1)], fs.arena[(size_t)(jf.vOff + 2 * k)]);
			double d2 = (pt.x - sx) * (pt.x - sx) + (pt.y - sy) * (pt.y - sy);
			if (d2 < best) { best = d2; kind = 1; idx = (int)t; }
		}
		for (size_t f = 0; f < fs.fronts.size(); f++) {
			const FrontFeature &ff = fs.fronts[f];
			if (ff.vCnt < 1) continue;
			int k = ff.vCnt / 2;
			GetCanvasPixLL(vpc, &pt, fs.arena[(size_t)(ff.vOff + 2 * k + 1)], fs.arena[(size_t)(ff.vOff + 2 * k)]);
			double d2 = (pt.x - sx) * (pt.x - sx) + (pt.y - sy) * (pt.y - sy);
			if (d2 < best) { best = d2; kind = 2; idx = (int)f; }
		}
	}
	if (kind < 0 || idx < 0) return false;

	if (kind == 0) {
		const EddyFeature &ef = fs.eddies[(size_t)idx];
		m_selFeatLon = ef.clon; m_selFeatLat = ef.clat;
		const char *nm = (ef.polarity > 0) ? "反气旋·暖芯" : "气旋·冷芯";
		char buf[512];
		snprintf(buf, sizeof(buf),
			"【中尺度涡 | %s】\n半径 %.0f km   振幅 %.0f cm   置信度 %.0f%%\n"
			"核温异常 %+.2f °C   核盐异常 %+.2f\n平均涡度 %.2e /s",
			nm, (double)(ef.radius_m / 1000.0), (double)(ef.amplitude_m * 100.0),
			(double)(ef.confidence * 100), (double)ef.coreTAnom, (double)ef.coreSAnom,
			(double)ef.meanVort);
		panel = wxString(buf);
	} else if (kind == 1) {
		const JetFeature &jf = fs.jets[(size_t)idx];
		int k = jf.vCnt / 2;
		m_selFeatLon = fs.arena[(size_t)(jf.vOff + 2 * k)];
		m_selFeatLat = fs.arena[(size_t)(jf.vOff + 2 * k + 1)];
		char buf[512];
		snprintf(buf, sizeof(buf),
			"【强流轴】\n平均流速 %.2f m/s   最大 %.2f m/s\n半高全宽 %.0f km",
			(double)jf.meanSpeed, (double)jf.maxSpeed, (double)(jf.width_m / 1000.0));
		panel = wxString(buf);
	} else if (kind == 2) {
		const FrontFeature &ff = fs.fronts[(size_t)idx];
		int k = ff.vCnt / 2;
		m_selFeatLon = fs.arena[(size_t)(ff.vOff + 2 * k)];
		m_selFeatLat = fs.arena[(size_t)(ff.vOff + 2 * k + 1)];
		const char *nm = (ff.cls == 0) ? "密度锋" : (ff.cls == 1) ? "温度锋(降级)" : "盐度锋(降级)";
		char buf[512];
		snprintf(buf, sizeof(buf),
			"【%s】 强度 %.0f%%\nΔT %.2f °C   Δσ %.4f   梯度 %.4f /km\n"
			"长度 %.0f km   跨锋流速差 %.2f m/s",
			nm, (double)(ff.strength * 100), (double)ff.dTemp, (double)ff.dSigma,
			(double)ff.gradPerKm, (double)ff.lengthKm, (double)ff.shearAcross);
		panel = wxString(buf);
	} else {
		const ZoneFeature &zf = fs.zones[(size_t)idx];
		const char *nm = (zf.kind == FK_CONVERG) ? "辐聚区" : (zf.kind == FK_DIVERG) ? "辐散区" : "剪切区";
		char buf[512];
		snprintf(buf, sizeof(buf),
			"【%s】\n均值 %.2f  峰值 %.2f (1e-6/s)\n面积 %.0f km2   强度 %.0f%%",
			nm, (double)zf.meanVal, (double)zf.peakVal,
			(double)zf.areaKm2, (double)(zf.strength * 100));
		panel = wxString(buf);
	}
	return true;
}

void MainDialog::fillDirTree(wxString path, bool start, wxTreeItemId id)
{
    ncdfLogW(L"[ncdf] fillDirTree: started, path=%ls, start=%d\n", (const wchar_t*)path.c_str(), (int)start);

	if(start == true)
	{
		ncdfLog("[ncdf] fillDirTree: deleting all tree items\n");

		m_isTreeUpdating = true;
		m_treeCtrl->Freeze();
		this->m_treeCtrl->DeleteAllItems();

		id = this->m_treeCtrl->AddRoot(_T(""));
		this->m_treeCtrl->SetItemText(id,_("ncdf-Files"));
		this->m_treeCtrl->SelectItem(id);
		// Keep m_isTreeUpdating=true and Freeze() active through addChildren loop
		ncdfLog("[ncdf] fillDirTree: root item created\n");
	}

	wxDir dir(path);
	if(dir.IsOpened() && dir.HasFiles())
	{
		ncdfLog("[ncdf] fillDirTree: directory opened successfully\n");

		wxString s;
		if (dir.GetFirst(&s, wxEmptyString, wxDIR_FILES)) {
			do {
				wxString ext = s.Mid(s.find_last_of('.') + 1).Lower();
				if (ext == "nc" || ext == "nc4") {
					ncdfLogW(L"[ncdf] fillDirTree: adding file: %ls\n", (const wchar_t*)s.c_str());

					wxTreeItemId iid = this->m_treeCtrl->AppendItem(id, s);

					ncdfLogW(L"[ncdf] fillDirTree: calling addChildren for %ls\n", (const wchar_t*)s.c_str());
					addChildren(iid, s);

					ncdfLog("[ncdf] fillDirTree: addChildren returned\n");
				}
			} while (dir.GetNext(&s));
		}
	}

	// Release tree update guard and thaw display
	m_isTreeUpdating = false;
	if (start) m_treeCtrl->Thaw();

	ncdfLog("[ncdf] fillDirTree: completed\n");
}

void MainDialog::addChildren(wxTreeItemId id, wxString fn)
{
    ncdfLogW(L"[ncdf] addChildren: started, fn=%ls\n", (const wchar_t*)fn.c_str());

	wxString fileName = this->m_textCtrlDir->GetValue()+_("\\")+fn;
	ncdfLogW(L"[ncdf] addChildren: fileName=%ls\n", (const wchar_t*)fileName.c_str());

	// Lightweight metadata read — no myDataVector allocation, no nc_get overhead
	FileMetadata meta = nc_read_metadata(fileName);
	if (!meta.valid) {
		ncdfLog("[ncdf] addChildren: nc_read_metadata failed for %s\n", (const char*)fileName.mb_str());
		return;
	}
	ncdfLog("[ncdf] addChildren: metadata OK, timelength=%zu hasCurrent=%d hasSST=%d hasSal=%d\n",
		meta.timelength, (int)meta.hasCurrent, (int)meta.hasSeaTemp, (int)meta.hasSalinity);

	for (size_t i = 0; i < meta.timelength; i++) {
		wxTreeItemId itemId = this->m_treeCtrl->AppendItem(id, _T(""));
		wxString timeText;
		if (meta.timeValid[i]) {
			timeText = meta.dates[i].Format(_T("%Y-%m-%d %H:00"));
		} else {
			timeText = wxString::Format(_("time%d"), (int)i + 1);
		}
		this->m_treeCtrl->SetItemText(itemId, timeText);
		MyTreeItemData* treeItemData = new MyTreeItemData((int)i);
		this->m_treeCtrl->SetItemData(itemId, treeItemData);
	}

	ncdfLog("[ncdf] addChildren: completed, %zu tree items created\n", meta.timelength);
}

void MainDialog::OnContextMenu(double m_lat, double m_lon){

	// show some info about this item
	wxTreeItemId itemId = m_treeCtrl->GetFocusedItem();
	MyTreeItemData *item = (MyTreeItemData *)this->m_treeCtrl->GetItemData(itemId);

	if (item == NULL)
	{
		return;
	}

	int response;
	wxMessageDialog *dial = new wxMessageDialog(NULL, _T("Show tidal current at the cursor position?"), wxT("Proceed?"), wxOK | wxCANCEL);

	response = dial->ShowModal();

	if (response == wxID_OK) {
		pPlugIn->b_showODAS = true;
		Arrow *m_Arrow = new Arrow;
		m_Arrow->m_lat = m_lat;
		m_Arrow->m_lon = m_lon;
		m_ArrowList.push_back(m_Arrow);
	}
	else{
		pPlugIn->b_showODAS = false;
		m_ArrowList.clear();

		return;
	}
}

